  "plugins.scripts.createPrompt":
    "帮我为 Snow App 制作一个客户端脚本（注入桌面窗口的油猴脚本）。\n\n我的需求：{{request}}\n\n请先加载 snow-app-docs 技能（内置文档技能），按它给出的路径阅读《油猴脚本》的「客户端脚本（桌面窗口）」章节，以文档为准而不是去搜应用源码；再按规范写一个完整的 .user.js：元数据头必须包含 @name 与 @snow-target client，并按需声明 @snow-view / @snow-surface / @snow-scope / @run-at。界面定制像 Chrome 油猴一样直接操作 DOM：隔离世界与页面共享 DOM，querySelector / createElement / append / MutationObserver / addEventListener 等原生 API 都能用；用锚点 data-snow-anchor（app.root、topbar、sidebar、sidebar.nav、sidebar.footer、main.view、chat.messages、chat.message、chat.input、rightPanel、rightPanel.tabs、rightPanel.content）与插槽 data-snow-slot（topbar.actions、sidebar.nav.actions、sidebar.footer.actions、chat.input.actions、chat.message.actions）定位，React 重建节点时用 MutationObserver 自行重挂；宿主只为 DOM 做不到的事提供 snow API（snow.on 事件、snow.client 应用动作等）。写好后用 config-set 的 userscripts 域安装并启用（key 用 new，value 里 sourcePath 传脚本文件的绝对路径），最后告诉我这个脚本怎么用、在哪些视图生效。",
  "plugins.scripts.importFile": "导入文件",
